/// <summary>
/// Data contract class for service <c>METSalesOrderLineCancelService</c>
/// </summary>
[DataContractAttribute]
public class METSalesOrderLineRequestContract extends METSalesOrderRequestContract
{
    LineNum lineNum;

}

Method.Source:
/// <summary>
/// Gets/sets the sales order line number
/// </summary>
/// <param name = "_lineNum">sales order line number</param>
/// <returns>return the sales order line number</returns>
[DataMemberAttribute('LineNumber')]
public LineNum parmLineNum(LineNum _lineNum = lineNum)
{
    lineNum = _lineNum;
    return lineNum;
}
